package com.termux.app.workspace;
import android.app.Application;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import org.robolectric.RuntimeEnvironment;import org.json.*;import java.io.File;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiLocationTest {
 @Test public void locationsPersistCopyAndDefaultWithoutChangingToolEnvironmentOrRights()throws Exception{WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.localLocation="ubuntu";p.localEnvironment="termux";p.localAccess="read";store.sessions.add(p);JSONObject data=store.encode();store.decode(data.toString());WorkspaceStore.Session out=store.sessions.get(0);assertEquals("ubuntu",out.localLocation);assertEquals("ubuntu",p.copy().localLocation);assertEquals("ubuntu",new LocalAiUi.Selection(p).location);assertEquals("termux",out.localEnvironment);assertEquals("read",out.localAccess);data.getJSONArray("sessions").getJSONObject(0).remove("localLocation");store.decode(data.toString());assertEquals("android",store.sessions.get(0).localLocation);}
 @Test public void invalidPersistedLocationsAreRejected()throws Exception{for(Object bad:new Object[]{"working-ubuntu","remote",4,JSONObject.NULL}){WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();store.sessions.add(new WorkspaceStore.Session());JSONObject data=store.encode();data.getJSONArray("sessions").getJSONObject(0).put("localLocation",bad);try{store.decode(data.toString());fail(String.valueOf(bad));}catch(JSONException expected){}}}
 @Test public void externalCommandOnlyMountsDedicatedUbuntuAndDoesNotIncludePromptOrShellExpansion()throws Exception{File bin=new File("/native dir/libjobs_runner_ubuntu.so"),model=new File("/models dir/odd'$(touch NEVER).gguf");String s=LocalAiProcess.command("ubuntu",bin,model);assertTrue(s.contains("--isolated"));assertTrue(s.contains("'jobs-local-ai'"));assertTrue(s.contains("'/native dir:/jobs-native'"));assertTrue(s.contains("'/models dir:/jobs-models'"));assertFalse(s.contains("touch NEVER"));assertFalse(s.contains(" -- ubuntu "));assertEquals("exec '/native dir/libjobs_runner_ubuntu.so'",LocalAiProcess.command("termux",bin,model));}
 @Test public void wirePromptKeepsOnlyRolesTextsAndSystemAndPreservesExactContents()throws Exception{JSONArray messages=new JSONArray().put(new JSONObject().put("role","user").put("text","line\n\"quote\"").put("toolOutput","not needed"));JSONObject wire=LocalAiProcess.prompt(messages,"settings");assertEquals("line\n\"quote\"",wire.getJSONArray("texts").getString(0));assertFalse(wire.toString().contains("not needed"));assertEquals(3,wire.length());}
 @Test public void modelInstructionsDistinguishInferenceLocationFromToolEnvironment(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localLocation="ubuntu";p.localEnvironment="termux";String text=LocalAiTools.instructions(p);assertTrue(text.contains("Inference location: ubuntu"));assertTrue(text.contains("dedicated jobs-local-ai"));assertTrue(text.contains("Tool environment: termux"));assertTrue(text.contains("Current action mode: write"));}
}
